import{_ as o,o as a,c as t,ag as r}from"./chunks/framework.CrXGS008.js";const m=JSON.parse('{"title":"Frameworks y recursos","description":"","frontmatter":{},"headers":[],"relativePath":"es/bridge/index.md","filePath":"es/bridge/index.md"}'),s={name:"es/bridge/index.md"};function n(d,e,i,c,l,u){return a(),t("div",null,[...e[0]||(e[0]=[r(`<h1 id="frameworks-y-recursos" tabindex="-1">Frameworks y recursos <a class="header-anchor" href="#frameworks-y-recursos" aria-label="Permalink to &quot;Frameworks y recursos&quot;">​</a></h1><p>Cada script Nayretis se comunica con tu servidor a través del bridge de <code>nay_lib</code>. Detecta tu framework, inventario, target y notificaciones la primera vez que se usa, así que el mismo script funciona en todas las configuraciones compatibles.</p><h2 id="configuraciones-compatibles" tabindex="-1">Configuraciones compatibles <a class="header-anchor" href="#configuraciones-compatibles" aria-label="Permalink to &quot;Configuraciones compatibles&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Módulo</th><th>Adaptadores</th><th>Alternativa</th></tr></thead><tbody><tr><td>Framework</td><td><code>qbox</code> (qbx_core), <code>ox</code> (ox_core), <code>esx</code> (es_extended), <code>qbcore</code> (qb-core), <code>custom</code></td><td>ninguna, el script se detiene con un error</td></tr><tr><td>Inventario</td><td><code>ox_inventory</code>, <code>qs-inventory</code>, <code>qb-inventory</code></td><td><code>framework</code> (el inventario propio del framework)</td></tr><tr><td>Target</td><td><code>ox_target</code>, <code>qb-target</code></td><td><code>none</code> (avisos de tecla)</td></tr><tr><td>Notificaciones</td><td><code>ox_lib</code>, <code>nayretis</code> (solo si se fuerza)</td><td><code>framework</code>, luego <code>native</code> (feed de GTA)</td></tr></tbody></table><p>La detección sigue el orden de la tabla. Inicia <code>nay_lib</code> <strong>después</strong> de los recursos de tu framework, inventario y target; si no, no se pueden detectar.</p><h2 id="forzar-un-adaptador" tabindex="-1">Forzar un adaptador <a class="header-anchor" href="#forzar-un-adaptador" aria-label="Permalink to &quot;Forzar un adaptador&quot;">​</a></h2><p>Si la detección elige el recurso equivocado, fuérzalo en <code>server.cfg</code> con <code>setr</code> (el cliente también lo lee):</p><div class="language-cfg vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cfg</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>setr nay:framework &quot;esx&quot;</span></span>
<span class="line"><span>setr nay:inventory &quot;ox_inventory&quot;</span></span>
<span class="line"><span>setr nay:target &quot;ox_target&quot;</span></span>
<span class="line"><span>setr nay:notify &quot;native&quot;</span></span></code></pre></div><p>Los valores son los nombres de adaptador de arriba, o <code>auto</code> (el valor por defecto). Consulta <a href="/es/nay-lib/convars">Convars</a>.</p><p>¿Usas un framework que no está en la lista? Escribe un <a href="/es/bridge/custom">adaptador personalizado</a>.</p><h2 id="limitaciones-conocidas" tabindex="-1">Limitaciones conocidas <a class="header-anchor" href="#limitaciones-conocidas" aria-label="Permalink to &quot;Limitaciones conocidas&quot;">​</a></h2><ul><li><strong>ox_core</strong>: no hay indicador de servicio, así que el grupo activo se trata como el trabajo en servicio. El rango más alto de un grupo cuenta como jefe.</li><li><strong>ox_inventory</strong> (con cualquier framework): los objetos usables deben existir en <code>ox_inventory/data/items.lua</code>. ox_inventory solo llama al callback del objeto para objetos sin <code>consume</code>, <code>client.export</code> ni <code>server.export</code>.</li><li><strong>qb-inventory</strong>: los metadatos de los objetos se ignoran al contarlos.</li><li><strong>qs-inventory</strong>: los resultados de añadir y quitar objetos no están documentados. Cualquier resultado distinto de <code>false</code> se trata como un éxito.</li><li><strong>ESX</strong>: las notificaciones usan <code>esx_notify</code> cuando está iniciado, y el feed de GTA en caso contrario.</li></ul>`,12)])])}const b=o(s,[["render",n]]);export{m as __pageData,b as default};
